import type { UpdatePublicKey } from "./update-signature.js";

/**
 * The public keys a downloaded update's `SHA256SUMS.txt.sig` must verify
 * against (update signing, option B; decisions/pending-update-signing).
 *
 * Signing is live from the build that added these keys (D44, #nqk8jijn): every
 * release must carry a `SHA256SUMS.txt.sig` that one of them verifies.
 *
 * Two ed25519 keys, generated by the owner on their own machine.
 * - primary: signs releases in CI (its private key in a protected
 *   "release" environment);
 * - backup: kept offline, used only if the primary is lost or leaked. A
 *   release signed with the backup is accepted by every app that has both
 *   keys, and the next release can ship a new pair (rotation).
 *
 * Public keys only, `{ id: keyIdOf(spkiDer), spki: spkiDer.toString("base64") }`.
 * Never put a private key, or a test key, in this file.
 *
 * WHEN THE KEYS GO IN: also pin their ids in test/update-signature.test.ts
 * (and keep the length at 2 or more), so a build that accidentally empties
 * this list, which silently turns verification off, fails CI.
 */
export const UPDATE_PUBLIC_KEYS: readonly UpdatePublicKey[] = [
  { id: "7d231848158a2a02", spki: "MCowBQYDK2VwAyEAwOvro8KsI8pQjKoo/eYt3CnOwYBdclQkcni2wXN71FY=" }, // primary (CI)
  { id: "3806c70f4944286f", spki: "MCowBQYDK2VwAyEArx0kocPX1L0FnzkFJvHE1HGmopLcD5AZxvunSF3aPw0=" }, // backup (offline)
];
